CREATE OR REPLACE VIEW "test_db"."PUBLIC"."REP_SFDC_SBQQ_QUOTE_HISTORY_LATEST" AS
SELECT "PARENT_ID", "CREATED_DATE", "NEWVALUE"
FROM "test_db"."PUBLIC"."REP_SFDC_SBQQ_QUOTE_HISTORY"
QUALIFY ROW_NUMBER() OVER (PARTITION BY "PARENT_ID" ORDER BY "CREATED_DATE" DESC NULLS LAST) = 1

CREATE OR REPLACE SEMANTIC VIEW "test_db"."PUBLIC"."CLIENT_DATA_SEMANTIC"
TABLES (
  SALES_FACT AS (
    SELECT 
        f.*,
        (SELECT MAX("MONTHINDEX") FROM "DATE_DIM" WHERE "DATE_ID" = CURRENT_DATE()) AS "_CURRENT_FISCAL_PERIOD"
    FROM "test_db"."PUBLIC"."SALES_FACT" f
) PRIMARY KEY ("CUSTOMER_ID"),
  DATE_DIM AS "test_db"."PUBLIC"."DATE_DIM" PRIMARY KEY ("DATE_ID"),
  REP_SFDC_SBQQ_QUOTE_HISTORY AS "test_db"."PUBLIC"."REP_SFDC_SBQQ_QUOTE_HISTORY_LATEST" PRIMARY KEY ("PARENT_ID")
)
RELATIONSHIPS (
  SALES_FACT_DATE_ID_DATE_DIM_DATE_ID AS SALES_FACT ("DATE_ID") REFERENCES DATE_DIM ("DATE_ID")
)
DIMENSIONS (
  SALES_FACT."STATUS" AS SALES_FACT."STATUS",
  DATE_DIM."YEAR" AS DATE_DIM."YEAR",
  SALES_FACT."CUSTOMER_ID" AS SALES_FACT."CUSTOMER_ID",
  SALES_FACT."DATE_ID" AS SALES_FACT."DATE_ID",
  SALES_FACT."REVENUE" AS SALES_FACT."REVENUE",
  SALES_FACT."QUANTITY" AS SALES_FACT."QUANTITY",
  DATE_DIM."DATE_ID_2" AS DATE_DIM."DATE_ID",
  REP_SFDC_SBQQ_QUOTE_HISTORY."PARENT_ID" AS REP_SFDC_SBQQ_QUOTE_HISTORY."PARENT_ID",
  REP_SFDC_SBQQ_QUOTE_HISTORY."CREATED_DATE" AS REP_SFDC_SBQQ_QUOTE_HISTORY."CREATED_DATE",
  REP_SFDC_SBQQ_QUOTE_HISTORY."NEWVALUE" AS REP_SFDC_SBQQ_QUOTE_HISTORY."NEWVALUE"
)
METRICS (
  SALES_FACT."TOTAL_REVENUE" AS SUM(SALES_FACT."REVENUE"::FLOAT),
  SALES_FACT."AVERAGE_QUANTITY" AS AVG(SALES_FACT."QUANTITY")
);